import { test, expect } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/new4.json') });

test.describe('История — пустое состояние', () => {
  test('История без сеансов: «עוד אין ניטורים» и кнопка «התחלת ניטור» #78e3149c #fb3b8d53 @iphone @prod-safe', async ({ page }) => {
    // 1. /home → таб «היסטוריה» → /history
    await page.goto('/home');
    await page.getByRole('tab', { name: 'היסטוריה' }).filter({ visible: true }).click();
    await expect(page).toHaveURL(/\/history/);

    await expect(page.getByRole('heading', { name: 'עוד אין ניטורים' }).filter({ visible: true })).toBeVisible();
    await expect(page.getByText('כאן יופיע כל ניטור שתעשו.').filter({ visible: true })).toBeVisible();
    // Кнопку «התחלת ניטור» не нажимать — создаст сеанс и сломает пустое состояние аккаунта
    await expect(page.getByRole('button', { name: 'התחלת ניטור', exact: true }).filter({ visible: true })).toBeVisible();

    // Записей нет, ошибки нет
    await expect(page.getByRole('button', { name: /דק׳ ניטור/ }).filter({ visible: true })).toHaveCount(0);
    await expect(page.getByText(/\d{1,2}:\d{2} ·/).filter({ visible: true })).toHaveCount(0);
    await expect(page.getByText(/משהו השתבש/).filter({ visible: true })).toHaveCount(0);
  });
});
